#!/bin/sh
# uninstall.sh — remove the VOWP / StackSpirit binaries, systemd user unit and
# cron watchdog.
#
# This removes only what scripts/install.sh installed, under either product
# name (vowp / stackspirit, vowp-daemon / stackspirit-daemon, vowp.service /
# stackspirit.service, vowp-watchdog.sh / stackspirit-watchdog.sh). A unit or
# watchdog that does not look generated by this installer is reported and kept. The node state in
# `$VOWP_HOME` (default ~/.vowp) is deliberately left alone; delete it by hand
# if you really want to discard the database, session logs and backups.
#
# Spec: docs/design/loops.md §10 (L8 — watchdog); node paths:
# docs/design/architecture.md §3.

set -eu

PROGRAM=uninstall.sh

DRY_RUN=0
KEEP_BINARY=0

LEGACY_CRON_MARKER='# vowp: 5-minute L8 watchdog check (managed by scripts/install.sh)'
NEW_CRON_MARKER='# stackspirit: 5-minute L8 watchdog check (managed by scripts/install.sh)'

usage() {
    cat <<'EOF'
Usage: uninstall.sh [options]

Stop and remove the VOWP or StackSpirit systemd user unit, the cron watchdog
and the installed binaries (both names). No root is required. Node state in
$VOWP_HOME / $STACKSPIRIT_HOME (default ~/.vowp) is kept, and a unit that this
installer did not generate is left alone.

Options:
  --keep-binary   leave the binaries in $HOME/.local/bin in place
  --dry-run       print every action without changing files, services or cron
  -h, --help      show this help
EOF
}

note() {
    printf '%s: %s\n' "$PROGRAM" "$*"
}

warn() {
    printf '%s: warning: %s\n' "$PROGRAM" "$*" >&2
}

die() {
    printf '%s: error: %s\n' "$PROGRAM" "$*" >&2
    exit 1
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --keep-binary)
            KEEP_BINARY=1
            shift
            ;;
        --dry-run)
            DRY_RUN=1
            shift
            ;;
        -h|--help)
            usage
            exit 0
            ;;
        --)
            shift
            break
            ;;
        *)
            die "unknown option: $1 (try --help)"
            ;;
    esac
done

[ "$#" -eq 0 ] || die "unexpected argument: $1"
[ -n "${HOME:-}" ] || die "HOME is not set"

BIN_DIR=$HOME/.local/bin
UNIT_DIR=$HOME/.config/systemd/user
NODE_HOME=${VOWP_HOME:-${STACKSPIRIT_HOME:-"$HOME/.vowp"}}
VOWP_HOME=$NODE_HOME
STACKSPIRIT_HOME=$NODE_HOME
export VOWP_HOME STACKSPIRIT_HOME

# A unit is ours only when its ExecStart is exactly the one the installer's
# templates write. Anything else (a hand-written or third-party unit with the
# same name) is foreign and is never stopped, disabled or deleted.
unit_is_ours() {
    grep -Eq '^ExecStart=%h/\.local/bin/(vowp|stackspirit) up --foreground$' "$1" 2>/dev/null
}

# A watchdog is ours when it is the installer's script or a link to one.
watchdog_is_ours() {
    if [ -L "$1" ]; then
        case $(readlink "$1") in
            vowp-watchdog.sh|stackspirit-watchdog.sh|*/vowp-watchdog.sh|*/stackspirit-watchdog.sh) return 0 ;;
            *) return 1 ;;
        esac
    fi
    grep -q 'L8 watchdog' "$1" 2>/dev/null
}

# A bin entry is ours when it is a regular file, or a link to the matching
# StackSpirit/VOWP name; a link pointing anywhere else is somebody else's.
bin_is_ours() {
    if [ -L "$1" ]; then
        case $(readlink "$1") in
            vowp|stackspirit|vowp-daemon|stackspirit-daemon|*/vowp|*/stackspirit|*/vowp-daemon|*/stackspirit-daemon) return 0 ;;
            *) return 1 ;;
        esac
    fi
    return 0
}

UNITS_OURS=
UNITS_FOREIGN=
for unit in vowp.service stackspirit.service; do
    if [ -e "$UNIT_DIR/$unit" ] || [ -L "$UNIT_DIR/$unit" ]; then
        if unit_is_ours "$UNIT_DIR/$unit"; then
            UNITS_OURS="$UNITS_OURS $unit"
        else
            UNITS_FOREIGN="$UNITS_FOREIGN $unit"
        fi
    fi
done
# With no unit file at all keep the old behaviour: try the legacy name once so
# a unit managed elsewhere is still stopped.
if [ -z "$UNITS_OURS" ] && [ -z "$UNITS_FOREIGN" ]; then
    UNITS_OURS=" vowp.service"
fi

BINARIES="vowp stackspirit vowp-daemon stackspirit-daemon"
WATCHDOGS="vowp-watchdog.sh stackspirit-watchdog.sh"

if [ "$DRY_RUN" -eq 1 ]; then
    note "dry-run: no files, services or crontabs will be changed"
    for unit in $UNITS_OURS; do
        note "would run: systemctl --user disable --now $unit"
        note "would remove $UNIT_DIR/$unit"
    done
    for unit in $UNITS_FOREIGN; do
        note "would keep $UNIT_DIR/$unit (not generated by scripts/install.sh)"
    done
    note "would run: systemctl --user daemon-reload"
    note "would remove the watchdog crontab entry (vowp or stackspirit)"
    for name in $WATCHDOGS; do
        if [ -e "$BIN_DIR/$name" ] || [ -L "$BIN_DIR/$name" ]; then
            if watchdog_is_ours "$BIN_DIR/$name"; then
                note "would remove $BIN_DIR/$name"
            else
                note "would keep $BIN_DIR/$name (not the installer's watchdog)"
            fi
        fi
    done
    for name in $BINARIES; do
        if [ -e "$BIN_DIR/$name" ] || [ -L "$BIN_DIR/$name" ]; then
            if [ "$KEEP_BINARY" -eq 1 ]; then
                note "would keep $BIN_DIR/$name (--keep-binary)"
            elif bin_is_ours "$BIN_DIR/$name"; then
                note "would remove $BIN_DIR/$name"
            else
                note "would keep $BIN_DIR/$name (a link to something else)"
            fi
        fi
    done
    note "would keep node state in $NODE_HOME"
    exit 0
fi

service_stopped=0
for unit in $UNITS_FOREIGN; do
    warn "$UNIT_DIR/$unit was not generated by scripts/install.sh; leaving it alone"
done
if [ -n "$UNITS_OURS" ]; then
    if command -v systemctl >/dev/null 2>&1; then
        for unit in $UNITS_OURS; do
            if systemctl --user disable --now "$unit"; then
                service_stopped=1
                note "disabled and stopped $unit"
            else
                warn "systemctl --user disable --now $unit failed; continuing"
            fi
        done
    else
        warn "systemctl not found; the user unit cannot be disabled"
    fi
fi

# Without systemd, ask the supervisor to stop itself. Skip this when the only
# unit present is somebody else's: its supervisor is not ours to stop.
if [ "$service_stopped" -eq 0 ] && [ -n "$UNITS_OURS" ]; then
    down_bin=
    for name in stackspirit vowp; do
        if [ -x "$BIN_DIR/$name" ]; then
            down_bin=$BIN_DIR/$name
            break
        fi
    done
    if [ -z "$down_bin" ]; then
        for name in stackspirit vowp; do
            if command -v "$name" >/dev/null 2>&1; then
                down_bin=$(command -v "$name")
                break
            fi
        done
    fi
    if [ -n "$down_bin" ]; then
        if "$down_bin" --home "$NODE_HOME" down; then
            note "asked the running supervisor to stop with '$down_bin --home $NODE_HOME down'"
        else
            warn "'$down_bin down' failed; the supervisor may still be running"
        fi
    else
        warn "vowp not found; stop any running supervisor manually"
    fi
fi

for unit in $UNITS_OURS; do
    if [ -e "$UNIT_DIR/$unit" ] || [ -L "$UNIT_DIR/$unit" ]; then
        rm -f "$UNIT_DIR/$unit"
        note "removed $UNIT_DIR/$unit"
    fi
done

if command -v systemctl >/dev/null 2>&1; then
    if systemctl --user daemon-reload; then
        :
    else
        warn "systemctl --user daemon-reload failed; run it after your user manager is available"
    fi
fi

remove_cron() {
    if ! command -v crontab >/dev/null 2>&1; then
        warn "crontab not found; remove the watchdog entry manually"
        return 0
    fi

    tmp=$(mktemp "${TMPDIR:-/tmp}/vowp-crontab.XXXXXX") || die "mktemp failed"
    trap 'rm -f "$tmp" "$tmp.filtered" "$tmp.err"' 0 1 2 15

    if ! crontab -l > "$tmp" 2> "$tmp.err"; then
        if grep -qi 'no crontab' "$tmp.err"; then
            : > "$tmp"
        else
            detail=$(head -n 1 "$tmp.err" 2>/dev/null || true)
            [ -n "$detail" ] || detail="unknown error"
            warn "could not read the crontab ($detail); leaving it unchanged"
            rm -f "$tmp" "$tmp.filtered" "$tmp.err"
            return 0
        fi
    fi
    awk -v legacy="$LEGACY_CRON_MARKER" -v current="$NEW_CRON_MARKER" '
        $0 == legacy || $0 == current { next }
        $0 ~ /^\*\/5 \* \* \* \* ".*\/(vowp|stackspirit)-watchdog\.sh" >\/dev\/null 2>&1$/ { next }
        { print }
    ' "$tmp" > "$tmp.filtered"

    if crontab "$tmp.filtered"; then
        note "removed the watchdog crontab entry"
    else
        warn "could not update the crontab; remove the watchdog entry manually"
    fi

    rm -f "$tmp" "$tmp.filtered" "$tmp.err"
}

remove_cron

for name in $WATCHDOGS; do
    path=$BIN_DIR/$name
    if [ -e "$path" ] || [ -L "$path" ]; then
        if watchdog_is_ours "$path"; then
            rm -f "$path"
            note "removed $path"
        else
            warn "$path is not the installer's watchdog; leaving it alone"
        fi
    fi
done

for name in $BINARIES; do
    path=$BIN_DIR/$name
    if [ -e "$path" ] || [ -L "$path" ]; then
        if [ "$KEEP_BINARY" -eq 1 ]; then
            note "kept $path (--keep-binary)"
        elif bin_is_ours "$path"; then
            rm -f "$path"
            note "removed $path"
        else
            warn "$path is a link to something else; leaving it alone"
        fi
    fi
done

note "kept node state in $NODE_HOME"
note "delete that directory by hand only if you want to discard the database and session logs"
